def _normalize_tier(value):
        if pd.isna(value):
            return pd.NA
        token = str(value).strip().lower()
        if not token:
            return pd.NA
        if "gold" in token or "goald" in token:
            return "Gold"
        if "silv" in token or "sliv" in token:
            return "Silver"
        if "bron" in token:
            return "Bronze"
        return pd.NA

